CREATE TABLE projects (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, description TEXT NOT NULL, goal TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'recruiting' CHECK(status IN ('idea','recruiting','active','completed','cancelled')), member_limit INTEGER NOT NULL CHECK(member_limit BETWEEN 2 AND 20), deadline TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE project_roles (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, UNIQUE(project_id,name));
CREATE TABLE project_applications (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), applicant_id TEXT NOT NULL REFERENCES users(id), role_id TEXT NOT NULL REFERENCES project_roles(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id,applicant_id));
CREATE TABLE project_members (project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), role_id TEXT REFERENCES project_roles(id), joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(project_id,user_id));
CREATE TABLE project_deliverables (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), author_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, url TEXT NOT NULL, contribution TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE portfolio_items (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), project_id TEXT REFERENCES projects(id), kind TEXT NOT NULL CHECK(kind IN ('certificate','research','mun','ielts','project','other')), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', source_url TEXT, visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('public','members','private')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected')), verified_by TEXT REFERENCES users(id), verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE portfolio_evidence (id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES portfolio_items(id), owner_id TEXT NOT NULL REFERENCES users(id), storage_key TEXT NOT NULL UNIQUE, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760), filename TEXT NOT NULL);
CREATE TABLE reviews (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), reviewer_id TEXT NOT NULL REFERENCES users(id), subject_id TEXT NOT NULL REFERENCES users(id), stars INTEGER NOT NULL CHECK(stars BETWEEN 1 AND 5), comment TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id,reviewer_id), CHECK(reviewer_id<>subject_id));
CREATE TABLE reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id), object_type TEXT NOT NULL CHECK(object_type IN ('user','project','portfolio','review')), object_id TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','resolved','dismissed')), reviewed_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE session_completions (session_id TEXT NOT NULL REFERENCES sessions(id), user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(session_id,user_id));
CREATE INDEX projects_status ON projects(status,deadline);
CREATE INDEX portfolio_owner ON portfolio_items(owner_id,status);
CREATE INDEX reports_status ON reports(status);
